#include <stdint.h>
#include <stddef.h>

int reg_write_field(uint32_t *reg, unsigned int offset, unsigned int width, uint32_t value)
{
    uint32_t mask;

    if (reg == NULL || width == 0u || width > 32u) {
        return -1;
    }
    if (offset > 31u || offset + width > 32u) {
        return -1;
    }

    /* width == 32 时 1u << 32 是未定义行为，必须单独给出全 1 掩码 */
    mask = (width == 32u) ? 0xFFFFFFFFu : ((1u << width) - 1u);
    if (width < 32u && value > mask) {
        return -1;
    }

    *reg = (*reg & ~(mask << offset)) | ((value & mask) << offset);
    return 0;
}
